{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "meniscus-rehab-strength-12wk",
    "name": "12-Week Post-Meniscus Strength & Ski Return Programme",
    "description": "A 12-week progressive strength plan for a 36-year-old male recreational lifter recovering from a right medial meniscus tear. No jumping, no deep knee flexion under load. Designed to rebuild lower-body strength, stability, and ski-specific capacity within surgical clearance parameters.",
    "type": "workout",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "fitness-ai",
      "tags": ["strength", "rehab", "knee", "meniscus", "skiing", "lower-body", "12-week"],
      "difficulty": "intermediate",
      "estimated_duration_days": 84,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-strength",
        "type": "primary",
        "category": "strength",
        "name": "Build Lower-Body and Full-Body Strength",
        "description": "Progressively increase strength in knee-safe movement patterns (hip hinge, partial squat, single-leg) to support return to skiing.",
        "target": {
          "metric": "session_rpe_avg",
          "target_value": 7,
          "unit": "rpe",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "ms-phase1-complete",
            "name": "Phase 1 Complete – Foundation Established",
            "reward_points": 100
          },
          {
            "id": "ms-phase2-complete",
            "name": "Phase 2 Complete – Strength Base Built",
            "reward_points": 200
          },
          {
            "id": "ms-phase3-complete",
            "name": "Phase 3 Complete – Ski-Ready Strength",
            "reward_points": 300
          }
        ]
      },
      {
        "id": "goal-ski-return",
        "type": "secondary",
        "category": "sport_specific",
        "name": "Return to Skiing Next Season",
        "description": "Develop the unilateral leg strength, hip stability, and posterior chain power needed for safe return to recreational skiing.",
        "milestones": [
          {
            "id": "ms-single-leg-strength",
            "name": "Single-leg press 1.5× bodyweight achieved",
            "reward_points": 150
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 60,
      "fitness_level": ["intermediate"],
      "equipment": [
        { "id": "barbell", "name": "Barbell", "required": true },
        { "id": "dumbbells", "name": "Dumbbells", "required": true },
        { "id": "cable-machine", "name": "Cable Machine", "required": true },
        { "id": "leg-press", "name": "Leg Press Machine", "required": true },
        { "id": "leg-curl", "name": "Leg Curl Machine", "required": true },
        { "id": "bench", "name": "Adjustable Bench", "required": true },
        { "id": "pull-up-bar", "name": "Pull-up Bar / Lat Pulldown", "required": false, "alternatives": ["lat-pulldown-machine"] },
        { "id": "resistance-bands", "name": "Resistance Bands", "required": false }
      ],
      "contraindications": [
        {
          "condition": "icd10:S83.2",
          "severity": "high",
          "action": "modify",
          "affected_activities": ["barbell-back-squat", "jump-squat", "box-jump", "deep-leg-press", "full-depth-goblet-squat"]
        },
        {
          "condition": "no_deep_knee_flexion_under_load",
          "severity": "high",
          "action": "exclude",
          "affected_activities": ["barbell-back-squat", "jump-squat", "box-jump"]
        },
        {
          "condition": "no_jumping",
          "severity": "high",
          "action": "exclude",
          "affected_activities": ["jump-squat", "box-jump", "depth-jump", "plyometric-lunge"]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 50,
        "max_minutes_per_day": 75
      }
    },
    "athlete_thresholds": {
      "body_weight_kg": 82
    },
    "phases": [
      {
        "id": "phase-1-foundation",
        "name": "Phase 1 – Foundation & Tissue Tolerance",
        "order": 1,
        "type": "accumulation",
        "description": "Weeks 1–4. Establish movement quality, tissue tolerance, and baseline strength. Knee range of motion limited to 0–60° under load. Focus on hip hinge, partial range leg press, and upper body pulling/pushing. High rep ranges, moderate load, controlled tempo.",
        "duration": { "value": 4, "unit": "weeks" },
        "weeks": [
          {
            "id": "p1-w1",
            "name": "Week 1",
            "order": 1,
            "days": [
              {
                "id": "p1-w1-d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Day A – Lower Body Focus",
                "estimated_duration_minutes": 60,
                "blocks": [
                  {
                    "id": "p1-w1-d1-warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1-w1-d1-bike",
                        "type": "cardio",
                        "name": "Stationary Bike (easy)",
                        "modality": "stationary_bike",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 8, "unit": "minutes" },
                          "intensity": { "type": "rpe", "target": { "min": 3, "max": 4 }, "zone_model": "rpe_borg_10" }
                        }
                      },
                      {
                        "id": "p1-w1-d1-glute-bridge-warmup",
                        "type": "exercise",
                        "exercise_ref": "glute-bridge",
                        "name": "Glute Bridge (bodyweight)",
                        "primary_muscles": ["glutes"],
                        "secondary_muscles": ["hamstrings", "lower_back"],
                        "movement_pattern": "hinge",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "target": 15 },
                          "rest": { "value": 45, "unit": "seconds" },
                          "weight": { "type": "bodyweight" }
                        }
                      },
                      {
                        "id": "p1-w1-d1-clamshell",
                        "type": "exercise",
                        "exercise_ref": "clamshell",
                        "name": "Clamshell (band optional)",
                        "primary_muscles": ["hip_abductors", "glutes"],
                        "movement_pattern": "isolation",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "target": 15 },
                          "rest": { "value": 30, "unit": "seconds" },
                          "weight": { "type": "bodyweight" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1-w1-d1-main",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1-w1-d1-leg-press",
                        "type": "exercise",
                        "exercise_ref": "leg-press-partial",
                        "name": "Leg Press – Partial Range (0–60° knee flexion)",
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings"],
                        "movement_pattern": "squat",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 12, "max": 15 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 60, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1-w1-d1-rdl",
                        "type": "exercise",
                        "exercise_ref": "romanian-deadlift",
                        "name": "Romanian Deadlift",
                        "primary_muscles": ["hamstrings", "glutes"],
                        "secondary_muscles": ["lower_back", "spinal_erectors"],
                        "movement_pattern": "hinge",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 50, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1-w1-d1-hip-thrust",
                        "type": "exercise",
                        "exercise_ref": "barbell-hip-thrust",
                        "name": "Barbell Hip Thrust",
                        "primary_muscles": ["glutes"],
                        "secondary_muscles": ["hamstrings", "lower_back"],
                        "movement_pattern": "hinge",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 12, "max": 15 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 60, "unit": "kg" }
                        }
                      },
                      {
                        "id": "p1-w1-d1-leg-curl",
